using System.Text.Json;
using Vemo.Core;
using Xunit;
namespace Vemo.Core.Tests;

public sealed class MobileTests : IDisposable
{
    readonly string root = Path.Combine(OperatingSystem.IsMacOS() ? "/private/tmp" : Path.GetTempPath(), "vemo-mobile-" + Guid.NewGuid());
    string Sync => Path.Combine(root, "sync"); readonly string recording = Guid.NewGuid().ToString();
    public void Dispose() { if (Directory.Exists(root)) Directory.Delete(root, true); }
    LibraryStore Open() { Directory.CreateDirectory(root); return new(Path.Combine(root, "state")); }
    string Request(LibraryStore store, bool completed = true, string? target = null, string? hashOverride = null, string? date = null) { var bytes = new byte[] { 1, 2, 3 }; var hash = Convert.ToHexStringLower(System.Security.Cryptography.SHA256.HashData(bytes)); var dir = Path.Combine(Sync, "recordings", recording, hash); Directory.CreateDirectory(dir); File.WriteAllBytes(Path.Combine(dir, "audio.m4a"), bytes); File.WriteAllText(Path.Combine(dir, "recording.json"), JsonSerializer.Serialize(new { schema_version = 1, recording_id = recording, audio_sha256 = hashOverride ?? hash, audio_bytes = 3, audio_file = "audio.m4a", recorded_at = date ?? "2026-10-17T00:30:00+14:00", title = "Mobile title", mode = "desktop", target_processor_id = target ?? store.ProcessorId, completed })); return dir; }
    [Fact] public async Task PartialWrongProcessorHashAndDateNeverComplete() { using var s = Open(); var a = new MobileFolderAdapter(s); a.Register(Sync); Request(s, false); Assert.Equal(0, (await a.ScanAsync()).Imported); Assert.Empty(s.Jobs); Request(s, target: Guid.NewGuid().ToString()); Assert.Single((await a.ScanAsync()).Issues); Request(s, hashOverride: new string('a', 64)); Assert.Single((await a.ScanAsync()).Issues); Request(s, date: "2026-02-30T12:00:00+09:00"); Assert.Single((await a.ScanAsync()).Issues); Assert.Empty(s.Jobs); }
    [Fact] public async Task IdentityDateResultAndPurgeSuppression() { using var s = Open(); var a = new MobileFolderAdapter(s); a.Register(Sync); var dir = Request(s); Assert.Equal(1, (await a.ScanAsync()).Imported); var j = Assert.Single(s.Jobs); Assert.Equal("2026-10-17T00:30:00+14:00", j.RecordedAt); Assert.Equal(0, (await a.ScanAsync()).Imported); s.TryStart(j.Id); s.SaveTranscript(j.Id, "ASR fixture"); s.Complete(j.Id, "# Fixture notes"); a.Publish(j.Id); var result = Path.Combine(Sync, "results", recording, j.AudioSha256, "result.json"); using (var doc = JsonDocument.Parse(File.ReadAllText(result))) { Assert.Equal(j.RecordedAt, doc.RootElement.GetProperty("recorded_at").GetString()); Assert.Equal(s.ProcessorId, doc.RootElement.GetProperty("processor_id").GetString()); Assert.Equal("ASR fixture", doc.RootElement.GetProperty("transcript").GetString()); Assert.Equal(8, doc.RootElement.EnumerateObject().Count()); } a.Publish(j.Id); s.Trash([j.Id]); s.Purge([j.Id]); Assert.Equal(0, (await a.ScanAsync()).Imported); Assert.True(File.Exists(Path.Combine(dir, "audio.m4a"))); Assert.True(File.Exists(result)); }
    [Fact] public async Task DuplicateKeysAndChangingIdentityRejected() { using var s = Open(); var a = new MobileFolderAdapter(s); a.Register(Sync); var dir = Request(s); var marker = Path.Combine(dir, "recording.json"); var text = File.ReadAllText(marker); File.WriteAllText(marker, text.Replace("\"completed\":true", "\"completed\":false,\"completed\":true")); Assert.Single((await a.ScanAsync()).Issues); Assert.Empty(s.Jobs); Request(s); await a.ScanAsync(); var j = Assert.Single(s.Jobs); s.TryStart(j.Id); s.SaveTranscript(j.Id, "Fixture"); s.Complete(j.Id, "Notes"); File.WriteAllText(marker, File.ReadAllText(marker).Replace("Mobile title", "Changed")); Assert.ThrowsAny<Exception>(() => a.Publish(j.Id)); Assert.Single((await a.ScanAsync()).Issues); }
    [Fact] public void ProcessorOwnershipAndLibraryExclusiveLock() { using var s = Open(); new MobileFolderAdapter(s).Register(Sync); using var other = new LibraryStore(Path.Combine(root, "other")); Assert.ThrowsAny<Exception>(() => new MobileFolderAdapter(other).Register(Sync)); Assert.ThrowsAny<Exception>(() => new LibraryStore(s.Root)); }
}
